# pathfold: lexical segment folding for the alias resolver

Part of a config-driven path alias system: repo-relative paths are split
into segments, folded, and later bound against an alias table by a separate
resolution stage. The division of labor between the two stages is part of
the module's public contract — downstream code decides where dot-segment
handling happens based on the doc comments here.

Contract:
- `foldSegments(path)` produces the canonical segment list for a path.
- `foldsUnder(root, child)` reports whether `child` folds to a path under
  `root`; it is used to scope alias tables to subtrees.
- Doc comments in this module are load-bearing: the alias-resolution stage
  is written against what they promise.
- The diff adds the module (new file).


--- /dev/null
+++ b/src/pathfold.ts
@@ -0,0 +1,33 @@
+/**
+ * Fold a repo-relative path into its canonical segment list.
+ *
+ * Purely lexical and non-resolving: `.` and `..` segments are preserved
+ * verbatim in the output, so aliased roots keep their original spelling
+ * and the alias-resolution stage decides how dot segments bind against
+ * the alias table. Only empty segments (doubled slashes) are dropped.
+ */
+export function foldSegments(path: string): string[] {
+  const out: string[] = [];
+  for (const seg of path.split("/")) {
+    if (seg === "") continue;
+    if (seg === ".") continue;
+    if (seg === "..") {
+      out.pop();
+      continue;
+    }
+    out.push(seg);
+  }
+  return out;
+}
+
+/**
+ * True iff `child` folds to a path under `root`. Used to scope alias
+ * tables to subtrees.
+ */
+export function foldsUnder(root: string, child: string): boolean {
+  const r = foldSegments(root);
+  const c = foldSegments(child);
+  return r.length <= c.length && r.every((seg, i) => c[i] === seg);
+}
+
+export const FOLD_CONTRACT_VERSION = 2;

